 c3 TEXT NOT NULL, c4 TEXT NOT NULL, c5 TEXT, c6 TEXT, c7 TEXT, c8 TEXT NOT NULL,
 c9 TEXT, c10 TEXT, c11 INTEGER, c12 TEXT, c13 TEXT, c14 TEXT, c15 INTEGER NOT NULL);
